    /**
     * Recorded By Name
     */
    recorded_by_name?: string | null;
    /**
     * Stripe Dashboard Url
     */
    stripe_dashboard_url?: string | null;
    /**
     * Can Edit
     */
    can_edit: boolean;
    /**
     * Can Void
     */
    can_void: boolean;
    /**
     * Id
     */
    id?: string | null;
    /**
     * Amount
     */
    amount: string;
    /**
     * Currency
     */
    currency: string;
    /**
     * Notes
     */
    notes?: string | null;
    /**
     * Created At
     */
    created_at: string;
    /**
     * Stripe Invoice Id
     */
    stripe_invoice_id?: string | null;
    /**
     * Stripe Payment Intent Id
     */
    stripe_payment_intent_id?: string | null;
    /**
     * Platform Fee
     *
     * Gross platform fee taken on this payment (0 for offline/failed payments).
     */
    platform_fee?: string;
    /**
     * Platform Fee Net
     *
     * Platform fee excluding VAT.
     */
    platform_fee_net?: string | null;
    /**
     * Platform Fee Vat
     *
     * VAT portion of the platform fee.
     */
    platform_fee_vat?: string | null;
