    /**
     * Is Current
     */
    is_current: boolean;
    member_status?: MembershipStatus | null;
    subscription?: RegisterSubscriptionSummarySchema | null;
    /**
     * Id
     */
    id?: string | null;
    /**
     * Full Name
     */
    full_name: string;
    /**
     * Email
     */
    email?: string | null;
    /**
     * Tier Name
     */
    tier_name?: string | null;
    /**
     * Questionnaire Name
     */
